def map_child_rows_by_name(child_rows):
    mapped = {}
    if not child_rows:
        return mapped
    for r in child_rows:
        key = r.get("name") or ("IDX-%s" % (r.get("idx") or 0))
        mapped[key] = r
    return mapped

try:
    rows = doc.get("custom_leave_approver_details") or []

    # prepare existing map to detect changes
    existing_map = {}
    if doc.get("name") and frappe.db.exists("Leave Application", doc.name):
        try:
            existing = frappe.get_doc("Leave Application", doc.name)
            existing_map = map_child_rows_by_name(existing.get("custom_leave_approver_details") or [])
        except Exception:
            existing_map = {}

    # determine overall approval & detect changed rows to pick last approver
    all_approved = True
    changed_rows = []

    for r in rows:
        status = (r.get("status") or "").strip()
        if status != "Approved":
            all_approved = False

        # timestamp candidate: prefer date, then modified, then idx
        if r.get("date"):
            ts_candidate = str(r.get("date"))
        elif r.get("modified") or r.get("modified_on"):
            ts_candidate = str(r.get("modified") or r.get("modified_on"))
        else:
            ts_candidate = "IDX-%s" % (r.get("idx") or 0)

        key = r.get("name") or ("IDX-%s" % (r.get("idx") or 0))
        prev = existing_map.get(key)
        prev_status = (prev.get("status") or "").strip() if prev else None

        # row considered changed if status changed vs stored doc, or new row with status set
        if prev and prev_status != status:
            changed_rows.append((ts_candidate, r))
        elif not prev and status:
            changed_rows.append((ts_candidate, r))

    # pick the most-recent changed row (if any) as the last approver
    last_approver = None
    last_ts = None

    if changed_rows:
        changed_rows.sort(key=lambda x: x[0], reverse=True)
        chosen_row = changed_rows[0][1]
        last_approver = chosen_row.get("approver") or chosen_row.get("modified_by")
        last_ts = changed_rows[0][0]
    else:
        # fallback: pick row with latest date/modified/idx that has an approver
        best_row = None
        best_ts = None
        for r in rows:
            if not r.get("approver") and not r.get("modified_by"):
                continue
            if r.get("date"):
                ts = str(r.get("date"))
            elif r.get("modified") or r.get("modified_on"):
                ts = str(r.get("modified") or r.get("modified_on"))
            else:
                ts = "IDX-%s" % (r.get("idx") or 0)

            if not best_ts or ts > best_ts:
                best_ts = ts
                best_row = r

        if best_row:
            last_approver = best_row.get("approver") or best_row.get("modified_by")
            last_ts = best_ts

    # --- APPLY CHANGES ---
    # If checkbox is checked, skip automatic status logic (do NOT modify doc.status)
    if not doc.get("custom_check"):
        # Run automatic status logic only when checkbox is NOT checked
        if rows:
            # New logic: if any status is neither Approved nor Rejected -> Open
            any_other = False
            any_rejected = False
            any_rows = False
            for r in rows:
                any_rows = True
                s = (r.get("status") or "").strip()
                # treat blank or any other text other than Approved/Rejected as "other"
                if s and s not in ("Approved", "Rejected"):
                    any_other = True
                if s == "Rejected":
                    any_rejected = True

            if any_other:
                doc.status = "Open"
            elif any_rejected:
                doc.status = "Rejected"
            else:
                # all rows are Approved (or there are no rows with status)
                doc.status = "Approved" if any_rows else (doc.status or "Open")

    # Always update leave_approver if we determined one
    if last_approver:
        doc.leave_approver = last_approver

    # Try to copy approver_name from the selected row (if available)
    if last_ts:
        for r in rows:
            if (r.get("date") and str(r.get("date")) == last_ts) or (
                str(last_ts).startswith("IDX-") and ("IDX-%s" % (r.get("idx") or 0)) == last_ts
            ):
                if r.get("approver_name"):
                    doc.leave_approver_name = r.get("approver_name")
                break

    # --- SUBMIT CONTROL FLAG ---
    # Set custom_disable_submit = 0 only when status is Approved, otherwise set to 1.
    # Add a field 'custom_disable_submit' (Check / Int) to the Doctype if it doesn't exist.
    try:
        if getattr(doc, "status", "") == "Approved":
            doc.custom_disable_submit = 0
        else:
            doc.custom_disable_submit = 1
    except Exception:
        # if field does not exist, ignore silently
        pass

except Exception:
    # fail-safe: do not block save on unexpected error
    pass

