def make_sales_order_from_work_order(source_name, target_doc=None):
    """
    Create Sales Order from Production Plan
    """

    def postprocess(source, target):
        # Set company from Production Plan
        target.company = source.company

    def update_item(source_doc, target_doc, source_parent):
        # Map Production Plan Item → Sales Order Item
        target_doc.item_code = source_doc.item_code
        target_doc.qty = source_doc.planned_qty
        target_doc.uom = source_doc.uom
        target_doc.warehouse = source_doc.warehouse

    sales_order = get_mapped_doc(
        "Production Plan",
        source_name,
        {
            "Production Plan": {
                "doctype": "Sales Order",
                "validation": {
                    "docstatus": ["=", 1]
                }
            },
            "Production Plan Item": {
                "doctype": "Sales Order Item",
                "postprocess": update_item
            }
        },
        target_doc,
        postprocess
    )

    return sales_order

