        all_grn_rows = frappe.db.get_all(
            "Stock Entry Detail",
            filters={"parent": ["in", grn_names]},
            fields=["item_code", "qty", "s_warehouse", "t_warehouse"]
        )
        for row in all_grn_rows:
            if row.s_warehouse and not row.t_warehouse:
                # RM going out
                rm_returned_map[row.item_code] = (
                    rm_returned_map.get(row.item_code, 0) + frappe.utils.flt(row.qty)
                )
            elif row.t_warehouse and not row.s_warehouse:
                # FG coming in
                fg_received_map[row.item_code] = (
                    fg_received_map.get(row.item_code, 0) + frappe.utils.flt(row.qty)
                )

    # ── Validate each row ──
    errors = []
    for row in doc.items:
        if not row.item_code:
            continue

        ic               = row.item_code
        requested        = frappe.utils.flt(row.qty)
        already_scrapped = already_scrapped_map.get(ic, 0)

        if ic in po_rm_qty_map:
