            sent_qty  = sent_map.get(ic, 0)
            returned  = rm_returned_map.get(ic, 0)
            remaining = sent_qty - returned - already_scrapped

        elif ic in po_fg_qty_map:
            # FG item — remaining = po_qty - received - already scrapped
            po_qty    = po_fg_qty_map.get(ic, 0)
            received  = fg_received_map.get(ic, 0)
            remaining = po_qty - received - already_scrapped

        else:
            errors.append(
                f"Row {row.idx}: Item <b>{ic}</b> is not in the PO RM or FG list."
            )
